import sys
only = set(sys.argv[1:])
os.makedirs(OUT, exist_ok=True)
for key, line in LINES.items():
    if only and key not in only:
        continue
    rid = key.rsplit('-', 1)[0]
    src = open(os.path.join(R, SRC[rid] + '.txt')).read()
    lines = src.split('\n')
    while lines and lines[-1].strip() == '':
        lines.pop()
    lines[-1] = line
    open(os.path.join(OUT, key + '.txt'), 'w').write('\n'.join(lines))
    print(key, len(lines))
